  function farY(x) { return H * 0.6 + Math.sin(x * 0.004 + 1.3) * H * 0.025 + Math.sin(x * 0.011 + 0.4) * H * 0.012; }
  function midY(x) { var d = (x - treeX) / (W * 0.28); return H * 0.71 - H * 0.075 * Math.exp(-d * d) + Math.sin(x * 0.006 + 2.1) * H * 0.012; }
